window.NPC_CHUNK_193 = [{"name":"Rivozair","cr":14,"xp":38400,"race":"Adult blue dragon","gender":"Female","age_category":"Adult","alignment":"LE","size":"Huge","type":"dragon","sub_types":["earth"],"templates_applied":"horned-devil-bound","init":5,"senses":["dragon senses","see in darkness"],"auras":["electricity (5 ft.)","frightful presence (180 ft., DC 22)"],"ac":37,"ac_touch":9,"ac_flat_footed":36,"ac_mods":"+4 armor, +1 Dex, +24 natural, -2 size","hp":200,"hd":"16d12+96","hd_value":16,"hp_mods":"regeneration 5 (good spells, good weapons)","fort":15,"ref":13,"will":13,"save_mods":"+4 vs. poison","dr":"5/magic","immunities":["electricity","paralysis","sleep"],"resists":["fire 30"],"sr":25,"weaknesses":["contract bound"],"speed":[{"type":"burrow","speed":20},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"land","speed":40}],"melee":"bite +23 (2d8+13), 2 claws +23 (2d6+9), tail slap +21 (2d6+13), 2 wings +21 (1d8+4)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon"},{"type":"desert thirst"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"create water"},{"spell":"ghost sound"},{"spell":"minor image"},{"spell":"ventriloquism"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"1 barbed devil 100%, level 8"}]},{"frequency":"3/day","spells":[{"spell":"dispel good"},{"spell":"fireball"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"invisibility"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"mage armor"},{"spell":"protection from chaos"},{"spell":"ray of enfeeblement"},{"spell":"reduce person"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":29,"dexterity":12,"constitution":21,"intelligence":16,"wisdom":17,"charisma":18,"baseatk":16,"cmb":27,"cmd":38,"cmd_special":"42 vs. trip","feats":[{"feat":"Arcane Strike"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":23},{"skill":"Fly","value":12},{"skill":"Intimidate","value":23},{"skill":"Knowledge (arcana)","value":22},{"skill":"Knowledge (religion)","value":22},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":22},{"skill":"Spellcraft","value":22},{"skill":"Stealth","value":12}],"languages":["Common","Auran","Draconic","Infernal"],"sq":["sound imitation"],"special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Rivozair's breath weapon is hellfire. Half of the damage is fire damage and half is damage from unholy energy."}],"before_combat":"Rivozair casts mage armor on herself well before combat begins.","during_combat":"Rivozair opens combat with her breath weapon, then circles back in flight, summons a barbed devil, and casts mirror image before landing amid the PCs to engage them in melee. In melee she uses Arcane Strike (the bonuses are included in her statistics above), using her breath weapon or a fireball now and then to hit multiple PCs at once. Against a single particularly dangerous foe, she retreats to range and hits that target with ray of enfeeblement and reduce person before returning to melee.","morale":"If reduced to fewer than 30 hit points, Rivozair casts invisibility and flees the region for a time; she may well return to attack the PCs again during the celebration of the Silver Span.","source":"AP 100, Pathfinder RPG Bestiary 4 56, Pathfinder RPG Bestiary 94"},{"name":"Corinstian Grivenner","cr":11,"xp":12800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Asmodeus","level":5},{"class":"exalted","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"senses":["darkvision 60 ft."],"ac":26,"ac_touch":13,"ac_flat_footed":26,"ac_mods":"+9 armor, +4 deflection, -1 Dex, +4 shield","hp":122,"hd":"12d8+65","hd_value":12,"fort":12,"ref":2,"will":12,"save_mods":"+4 profane bonus vs. fire","speed":[{"type":"land","speed":20}],"melee":"+2 unholy heavy mace +16 (1d8+8)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, DC 13, 3d6"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"protection from good"}]},{"frequency":"1/day","spells":[{"spell":"deeper darkness"}]},{"frequency":"7/day","spells":[{"spell":"copycat","details":"7 rounds"},{"spell":"fire bolt","details":"1d6+2 fire"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":12,"spellsprepared_concentration":16,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"heal"},{"spell":"mislead","type":"domain"},{"spell":"quickened hold person"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"fire shield","type":"domain"},{"spell":"flame strike"},{"spell":"greater command"},{"spell":"quickened divine favor"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"cure critical wounds"},{"spell":"freedom of movement"},{"spell":"greater magic weapon"},{"spell":"sending"},{"spell":"unholy blight","type":"domain"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"fireball","type":"domain"},{"spell":"magic vestment","count":2}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bull's strength"},{"spell":"death knell"},{"spell":"produce flame","type":"domain"},{"spell":"resist energy"},{"spell":"spiritual weapon"},{"spell":"status"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"command","type":"domain"},{"spell":"cure light wounds","count":3},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"read magic"}]}],"spelldomains":"Devil, Evil, Fire","strength":16,"dexterity":8,"constitution":18,"intelligence":10,"wisdom":18,"charisma":13,"baseatk":8,"cmb":14,"cmd":24,"feats":[{"feat":"Craft Wondrous Item"},{"feat":"Deific Obedience"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell"},{"feat":"Selective Channeling"},{"feat":"Skill Focus (Knowledge religion)"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":1,"special":"+2 when divine brand is visible"},{"skill":"Diplomacy","value":14,"special":"+2 when divine brand is visible"},{"skill":"Disguise","value":-7},{"skill":"Intimidate","value":10},{"skill":"Knowledge (local)","value":7},{"skill":"Knowledge (religion)","value":19},{"skill":"Spellcraft","value":9}],"languages":["Common"],"sq":["+4 to save vs. fire effects","divine brand","domain (trickery)","hell's corruption","religious speaker","vitality"],"gear":"chainmail, buckler, +1 unholy heavy mace, belt of mighty constitution +2, rod of lesser extend metamagic, 533 gp","before_combat":"Corinstian takes time to cast magic vestment on his buckler and chainmail and greater magic weapon on his unholy heavy mace before combat. If he notices intruders, he also casts bull's strength and shield of faith on himself (enhancing both with his metamagic rod) in anticipation of a fight. He also casts status every day on a group of four erinyes devils, using his lesser rod of extend metamagic, then sends those devils to guard area E33.","during_combat":"Once he's attacked, Corinstian moves to the edge of the hellfire so he benefits from concealment from foes but his own vision isn't blocked. In so doing, he makes sure he's positioned such that one of the Asmodean priests can come cast shield other on him as soon as possible. He supports his minions with ranged spells, but focuses on defending his lover Aluceda Zhol if she's being attacked. In melee, he casts quickened divine favor (this is included in his statistics above) and casts fire shield before moving to use his mace, preferring to strike those who appear to be divine spellcasters of good or chaotic faiths. If he notices the devils in area E33 are being harmed or attacked via his status spell, he alerts those in the nave and sounds the alarm, then sends Aluceda up to alert Barzillai so that they can join in the defense of the chamber.","morale":"Corinstian fights to the death.","source":"AP 100, Pathfinder Campaign Setting: Inner Sea Gods 200"},{"name":"Aluceda Zhol","cr":12,"xp":19200,"race":"elf","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of zon-kuthon","level":7},{"class":"umbral court agent","level":4}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["elf","humanoid"],"templates_applied":"vampire","init":9,"senses":["darkvision 90 ft.","low-light vision"],"ac":30,"ac_touch":19,"ac_flat_footed":24,"ac_mods":"+5 armor, +3 deflection, +5 Dex, +1 dodge, +6 natural","hp":137,"hd":"11d8+84","hd_value":11,"hp_mods":"fast healing 5","fort":14,"ref":11,"will":14,"save_mods":"+2 vs. enchantments, +4 vs. channeled energy","defensive_abilities":["channel resistance +4"],"dr":"10/magic and silver","immunities":["sleep","undead traits"],"resists":["cold 10","electricity 10"],"sr":22,"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"slam +11 (1d4+4 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"channel negative energy","details":"9/day, DC 19, 4d6"},{"type":"children of the night"},{"type":"create spawn"},{"type":"death's kiss"},{"type":"dominate","details":"DC 21"},{"type":"energy drain","details":"2 levels, DC 21"},{"type":"shadow chains"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"touch of darkness","details":"5 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":10,"spellsprepared_concentration":14,"spellsprepared":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"slay living"},{"spell":"spell resistance"},{"spell":"summon monster VD"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"air walk"},{"spell":"enervation","type":"domain"},{"spell":"poison"},{"spell":"sending"},{"spell":"spell immunity"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"contagion"},{"spell":"deeper darkness","type":"domain"},{"spell":"dispel magic"},{"spell":"speak with dead"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blindness/deafness","type":"domain"},{"spell":"bull's strength"},{"spell":"death knell"},{"spell":"hold person"},{"spell":"sound burst"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"command","count":2},{"spell":"divine favor"},{"spell":"obscuring mist","type":"domain"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"stabilize"}]}],"spelldomains":"Darkness, Undead","strength":16,"dexterity":20,"intelligence":16,"wisdom":18,"charisma":22,"baseatk":8,"cmb":11,"cmd":30,"feats":[{"feat":"Alertness"},{"feat":"Blind-fight"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Craft Wondrous Item"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Tenebrous Spell"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":36},{"skill":"Diplomacy","value":10},{"skill":"Disguise","value":21},{"skill":"Knowledge (nobility)","value":21},{"skill":"Knowledge (religion)","value":17},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":14},{"skill":"Spellcraft","value":17},{"skill":"Stealth","value":13}],"languages":["Common","Elven","Infernal","Necril","Shadowtongue"],"sq":["blessings of darkness","change shape","elven magic","eyes of darkness (5 rounds/day)","gaseous form","shadow jump","shadowless","spider climb","tenebrous magic"],"special_abilities":[{"type":"Blessings of Darkness","details":"Aluceda's cleric levels stack with her umbral court agent levels for the purpose of determining the effects of her Darkness domain abilities."},{"type":"Shadow Chains","kind":"Sp","details":"When Aluceda uses her touch of darkness ability, she manifests shadowy chains that increase the reach of her touch attack by 5 feet. A creature struck by this attack must succeed at a DC 18 Reflex save or be entangled for 1d4 rounds in addition to the normal effects of the ability."},{"type":"Shadow Jump","kind":"Su","details":"This ability functions as the shadowdancer ability of the same name. Tenebrous Magic Aluceda receives the Tenebrous Spell feat as a bonus feat and can apply its effects without increasing the spell's level (all of her spells have been enhanced by this feat). This feat (detailed on page 15 of Pathfinder Campaign Setting: Inner Sea Magic) boosts a spell's effective caster level and save DCs by 1 when the spell is cast in darkness or dim light, and attempts to dispel such a spell take a -2 penalty (double these modifiers if the spell has the darkness or shadow descriptor or is of the shadow subschool). She must succeed at a concentration check (DC = 15 + 2 x spell's level) to cast such a spell in bright light, and attempts to dispel such a spell in bright light gain a +4 bonus."},{"type":"Umbral Courtier","kind":"Ex","details":"Aluceda gains a +4 competence bonus on Bluff, Diplomacy, and Knowledge (nobility) checks- these bonuses are included in her statistics above."}],"gear":"+2 glamered studded leather, cloak of fangs, glove of storing, headband of mental prowess +2 (Wis, Cha), wand of enervation (9 charges)","before_combat":"Aluceda casts air walk, magic vestment, spell resistance, and shield of faith before combat.","during_combat":"Aluceda uses air walk to stay away from melee, then uses ranged spells on foes; she starts with a summon monster V and follows with other spells thereafter, but tries to stay within 30 ft. of at least one PC so she can attempt to dominate that PC with her gaze if the opportunity presents itself. She uses touch spells in melee, but often holds the charge and then delivers them with her slam attack so she can use energy drain  on foes at the same time. If Corinstian is defeated, she alerts Barzillai with a sending unless the inquisitor has already joined the fight, then retreats to area E9 to join her minions there.","morale":"Aluceda fights until destroyed, then becomes gaseous and retreats to her closest coffin (in area E9).","source":"AP 100, Pathfinder RPG Bestiary 270, Pathfinder Campaign Setting: Paths of Prestige 58"},{"name":"Asmodean Priest","cr":6,"xp":2400,"race":"human","age_category":"Adult","classes":[{"class":"cleric of Asmodeus","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+7 armor, -1 Dex, +2 shield","hp":63,"hd":"7d8+28","hd_value":7,"fort":7,"ref":1,"will":9,"resists":["fire 10"],"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+1 heavy mace +8 (1d8+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, DC 14, 4d6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"fire bolt","details":"1d6+3 fire"},{"spell":"touch of law"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":7,"spellsprepared_concentration":11,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"air walk"},{"spell":"order's wrath","type":"domain"},{"spell":"sending"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"cure serious wounds","count":2},{"spell":"dispel magic"},{"spell":"fireball","type":"domain"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds","count":2},{"spell":"hold person"},{"spell":"produce flame","type":"domain"},{"spell":"shield other"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"burning hands","type":"domain"},{"spell":"command"},{"spell":"cure light wounds","count":3},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"}]}],"spelldomains":"Fire, Law","strength":12,"dexterity":8,"constitution":14,"intelligence":10,"wisdom":18,"charisma":13,"baseatk":5,"cmb":6,"cmd":15,"feats":[{"feat":"Brew Potion"},{"feat":"Combat Casting"},{"feat":"Selective Channeling"},{"feat":"Toughness"},{"feat":"Weapon Focus (heavy mace)"}],"skills":[{"skill":"Intimidate","value":8},{"skill":"Knowledge (religion)","value":10},{"skill":"Spellcraft","value":10}],"languages":["Common"],"gear":"+1 chainmail, +1 light steel shield, +1 heavy mace, silver holy symbol of Asmodeus, 20 gp, 6 sp, 7 cp, potion of cure moderate wounds (3), potion of cure serious wounds (2)","during_combat":"These priests protect their superiors; when in the presence of Aluceda or Corinstian, one priest moves to cast shield other on a superior while others move in to refresh the spell as their  colleagues die. They use sending to raise alerts, and air walk to pursue fleeing foes. Otherwise, the priests focus on channeling energy or using their attack spells. They switch to melee only when forced, or when doing so would prevent a foe from engaging a superior in melee. An Asmodean priest prefers to save his healing spells to aid his betters, but if reduced to 10 or fewer hit points, he casts sanctuary and then moves to support allies with healing rather than continue direct combat.","morale":"Asmodean priests fight to the death.","source":"AP 100"},{"name":"Serpent Of Darkness","cr":13,"xp":25600,"race":"amphisbaena","age_category":"Adult","alignment":"N","size":"Huge","type":"magical beast","sub_types":["extraplanar"],"templates_applied":"advanced, fiendish","init":8,"senses":["all-around vision","darkvision 60 ft.","low-light vision","scent","see in darkness"],"ac":27,"ac_touch":13,"ac_flat_footed":22,"ac_mods":"+4 Dex, +1 dodge, +14 natural, -2 size","hp":174,"hd":"6d10+65","hd_value":6,"hp_mods":"fast healing 5 (only in darkness)","fort":13,"ref":12,"will":7,"defensive_abilities":["split"],"dr":"10/good","immunities":["petrification"],"resists":["cold 15","fire 15"],"sr":18,"weaknesses":["darkness dependency"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":20},{"type":"swim","speed":20}],"melee":"2 bites +19 (3d6+8/19-20)","space":"15 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"smite good"}],"strength":26,"dexterity":18,"constitution":21,"intelligence":5,"wisdom":17,"charisma":8,"baseatk":13,"cmb":23,"cmd":38,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (poison)"},{"feat":"Dodge"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Armor"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Climb","value":16},{"skill":"Perception","value":23},{"skill":"Stealth","value":0},{"skill":"Swim","value":16}],"languages":["Infernal (cannot speak)"],"special_abilities":[{"type":"Darkness Dependency","kind":"Ex","details":"While in darkness, the serpent of darkness has fast healing 5. Outside of darkness, the serpent of darkness loses its fast healing, its damage reduction, and its spell resistance, and takes a -4 penalty on all attack rolls and saving throws."}],"during_combat":"The serpent of darkness prefers to attack the strongest, most heavily armored foes if an obvious champion of a good deity isn't apparent. It uses smites good with its first attack in combat, and is fond of using Power Attack (taking a -4 penalty to deal 8 extra points of damage on each hit), but abandons this tactic if it can't hit its current foe with at least one bite per round.","morale":"The serpent of darkness fights to the death in the dark, but if reduced to 40 hp or less while in any amount of light, it flees to find a dark place to hide and heal.","source":"AP 100, Pathfinder RPG Bestiary 2 292, 25"},{"name":"Zella Zidlii","cr":10,"xp":9600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"harrower","level":6},{"class":"wizard","level":5}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":24,"ac_touch":16,"ac_flat_footed":19,"ac_mods":"+4 armor, +1 deflection, +4 Dex, +1 dodge, +4 shield","hp":105,"hd":"11d6+64","hd_value":11,"fort":7,"ref":8,"will":9,"save_mods":"+1 vs. enchantment","speed":[{"type":"land","speed":30}],"melee":"+2 defending bladed scarf +11 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hand of the apprentice","details":"7/day"},{"type":"harrow casting"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"divination"}]}],"spellsprepared_caster":"wizard","spellsprepared_caster_level":11,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":6,"spell_slots":1,"spells":[{"spell":"chain lightning"}]},{"spell_level":5,"spell_slots":2,"spells":[{"spell":"prying eyes"},{"spell":"sending"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"black tentacles"},{"spell":"dimension door"},{"spell":"locate creature"},{"spell":"scrying"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"haste"},{"spell":"spiked pit"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cat's grace"},{"spell":"create pit"},{"spell":"false life"},{"spell":"glitterdust"},{"spell":"rope trick"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"light"},{"spell":"message"}]}],"strength":10,"dexterity":18,"constitution":16,"intelligence":18,"wisdom":12,"charisma":8,"baseatk":5,"cmb":5,"cmd":21,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Casting"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (bladed scarf)"},{"feat":"Harrowed"},{"feat":"Scribe Scroll"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Craft (painting)","value":16},{"skill":"Fly","value":18},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (religion)","value":18},{"skill":"Perception","value":12},{"skill":"Perform (string instruments)","value":13},{"skill":"Spellcraft","value":18}],"languages":["Common","Draconic","Infernal","Shadowtongue","Shoanti","Varisian"],"sq":["arcane bond (+2 defending bladed scarf)","blessing of the harrow","spirit deck","tower of charisma","tower of intelligence","tower of strength"],"special_abilities":[{"type":"Blessing of the Harrow","kind":"Su","details":"Once per day, Zella can spend 10 minutes to provide a 24-hour-long bonus by performing a harrowing for herself and all allies within 20 feet. Roll 1d6 to determine the results: 1 = +1 on all attack rolls, 2 = +1 to AC, 3 = +1 on weapon damage rolls, 4 = +1 on all skill checks, 5 = +1 on all saving throws, 6 = +1 on caster level checks and concentration checks. Harrower Abilities To speed game play, Zella's harrower class abilities presented here use die rolls to resolve their effects, but you can use the rules given in the harrower prestige class if you have a Pathfinder Cards: Deluxe Harrow Deck."},{"type":"Harrow Casting","kind":"Su","details":"Up to six times per day, Zella can perform a harrow casting by adding a somatic component and focus component (her harrow deck) to a spell as she casts it. When she does so, she rolls 1d6 three times: 1 = Zella gains the tower of charisma; 2 = Zella gains the tower of intelligence; 3 = Zella gains the tower of strength. The bonuses granted by these tower effects stack. She gains no benefit from results of 4-6."},{"type":"Spirit Deck","kind":"Su","details":"As a standard action once per day, Zella can create a translucent harrow deck made of force and cause it to strike a target within 30 feet. She rolls 1d6 six times to determine how much force damage the deck deals (the results are cumulative): 1 = 5 points of damage; 2-3 = 3 points of damage; 4-5 = 1 point of damage; 6 = 0 points."},{"type":"Tower of Charisma","kind":"Su","details":"Each time she rolls a 1 when using harrow casting, Zella increases the spell's save DC by 1."},{"type":"Tower of Intelligence","kind":"Su","details":"Each time she rolls a 2 when using harrow casting, Zella adds a +1 bonus on rolls made to penetrate Spell Resistance."},{"type":"Tower of Strength","kind":"Su","details":"Each time she rolls a 3 when using harrow casting, Zella's spell deals 1 extra point of damage per damage die (if the spell deals hit point damage)."}],"gear":"+2 defending bladed scarf, belt of mighty constitution +2, cloak of resistance +1, ring of protection +1, infernal-themed harrow deck worth 600 gp, 146 gp","before_combat":"Zella casts cat's grace, mage armor, false life, and shield before combat. In addition, each morning she performs a blessing of the harrow for Barzillai. Make sure to note what effect her blessing grants to herself and Barzillai (since this is a random bonus, it isn't already calculated into her statistics or Barzillai's).","during_combat":"Zella begins combat with chain lightning, then follows with her pit spells to keep the PCs from controlling the battlefield. She enjoys using her spirit deck attack on severely wounded enemies in hopes of killing them with the attack. If forced into melee, she fights with her bladed scarf, using its bonus to aid her AC while she seeks to move to range or find allies so she can return to spellcasting.","morale":"Zella is eager to meet her final reward in Hell, but believes suicide will undo her hard work. She fights to the death as a result.","source":"AP 100, Pathfinder Campaign Setting: The Inner Sea World Guide 276"},{"name":"Vampiric Hound","cr":11,"xp":12800,"race":"shadow mastiff","age_category":"Adult","alignment":"LE","size":"Large","type":"undead","sub_types":["evil","extraplanar","outsider"],"templates_applied":"vampire","init":7,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":13,"ac_flat_footed":23,"ac_mods":"+3 Dex, +1 dodge, +14 natural, -1 size","hp":135,"hd":"6d8+70","hd_value":6,"hp_mods":"fast healing 5","fort":15,"ref":14,"will":9,"save_mods":"+6 vs. channeled positive energy","defensive_abilities":["channel resistance +4","shadow blend"],"dr":"10/magic, 10/silver","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":50}],"melee":"bite +22 (3d6+13), slam +22 (1d8+13), tail slap +17 (1d8+7)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bay"},{"type":"blood drain"},{"type":"children of the night"},{"type":"create spawn"},{"type":"dominate","details":"DC 19"},{"type":"energy drain","details":"2 levels, DC 19"}],"strength":33,"dexterity":17,"intelligence":6,"wisdom":14,"charisma":18,"baseatk":10,"cmb":24,"cmd":36,"cmd_special":"40 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":13,"special":"+8 when jumping"},{"skill":"Bluff","value":12},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":20}],"languages":["Common (can't speak)"],"sq":["change shape (dire bat or wolf, beast shape II)","gaseous form","shadowless","spider climb"],"during_combat":"The vampiric hound begins combat by baying. The walls of this room block the bay's effects from affecting creatures in nearby rooms, but don't block the sound entirely. If she hasn't already been defeated, Aluceda comes to investigate this room in 1d4+2 rounds. After it bays, the vampiric hound moves to attack the creature closest to its mistress's coffin, making slam attacks on rounds during which it can't make full attacks.","morale":"The vampiric hound fights to the death. If defeated, it becomes gaseous and retreats to its coffin in area E12.","source":"AP 100, Pathfinder RPG Bestiary 3 241, Pathfinder RPG Bestiary 270"},{"name":"The Gardener","cr":12,"xp":19200,"race":"vishkanya","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":12}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["vishkanya"],"init":3,"senses":["low-light vision"],"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+4 armor, +3 Dex, +1 dodge, +1 insight, +4 shield","hp":111,"hd":"12d6+67","hd_value":12,"fort":6,"ref":7,"will":8,"save_mods":"+12 bonus vs. poison","defensive_abilities":["poison resistance"],"dr":"10/adamantine, 10/lethal","resists":["cold 10"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 disruption light mace +6 (1d6)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"grasp of the dead","details":"12d6 slashing"}]},{"frequency":"7/day","spells":[{"spell":"grave touch","details":"6 rounds"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":12,"spellsknown_concentration":16,"spellsknown":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"chain lightning"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"cone of cold"},{"spell":"telekinesis"},{"spell":"waves of fatigue"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"animate dead"},{"spell":"dimension door"},{"spell":"phantasmal killer"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"fly"},{"spell":"halt undead"},{"spell":"haste"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"false life"},{"spell":"ghoul touch"},{"spell":"invisibility"},{"spell":"mirror image"},{"spell":"see invisibility"},{"spell":"spectral hand"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"chill touch"},{"spell":"detect undead"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"touch of fatigue"}]}],"bloodline":"undead","strength":9,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":10,"charisma":18,"baseatk":6,"cmb":5,"cmd":20,"feats":[{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Quicken Spell"},{"feat":"Still Spell"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Craft (alchemy)","value":7},{"skill":"Craft (sculpture)","value":9},{"skill":"Escape Artist","value":5},{"skill":"Fly","value":13},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (nature)","value":4},{"skill":"Perception","value":6},{"skill":"Stealth","value":5}],"languages":["Common","Vishkanya"],"sq":["bloodline arcana (corporeal undead affected by humanoid-affecting spells)","poison use","toxic"],"gear":"+1 disruption light mace, dusty rose prism ioun stone, handy haversack, 48 gp, 3 sp, 3 cp, scroll of break enchantment, scroll of displacement, scroll of greater invisibility, scroll of speak with dead, scroll of teleport","before_combat":"The Gardener casts stoneskin, mage armor, shield, fly, and false life before combat.","during_combat":"The Gardener favors area-effect spells in combat, and tries to stay at range, moving between attacks to minimize the number of full attacks made against her. She casts  quickened mirror image on the first round of the fight, then quickened spectral hand on the second round, saving a 6th-level slot for chain lightning. She uses vampiric touch often once her spectral hand is active.","morale":"The Gardener fights until reduced to 20 hit points or fewer, at which point she surrenders and offers to join the PCs. She honors her word and fights with them until they encounter Barzillai, at which point she betrays the PCs and attacks them once more, this time fighting to the death.","source":"AP 100, Pathfinder RPG Bestiary 3 281"},{"name":"Asmoden","cr":13,"xp":25600,"race":"huecuva","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":11}],"alignment":"CE","size":"Medium","type":"undead","templates_applied":"divine guardian","init":8,"senses":["blindsense 30 ft.","darkvision 60 ft.","low-light vision"],"auras":["faithlessness (30 ft.)"],"ac":29,"ac_touch":18,"ac_flat_footed":25,"ac_mods":"+8 armor, +4 deflection, +4 Dex, +3 natural","hp":200,"hd":"14d8+138","hd_value":14,"hp_mods":"fast healing 5","fort":12,"ref":10,"will":15,"save_mods":"+2 vs. channel and positive energy effects+6 vs. channeled positive energy","defensive_abilities":["ability healing"],"dr":"5/magic or silver","immunities":["undead traits"],"sr":23,"weaknesses":["missing arm"],"speed":[{"type":"land","speed":60}],"melee":"+2 Human-bane mithral longsword +22 (1d8+11/17-20 plus 2d6 vs. Human) or claw +14 (1d4+7 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"disease"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dimension door","details":"within sacred site only"}]},{"frequency":"1/day","spells":[{"spell":"arcane lock"},{"spell":"augury"},{"spell":"clairaudience/clairvoyance"},{"spell":"commune"},{"spell":"dismissal"},{"spell":"forbiddance"},{"spell":"guards and wards"},{"spell":"hold portal"}]},{"frequency":"3/day","spells":[{"spell":"alarm"},{"spell":"knock"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":11,"spellsknown_concentration":17,"spellsknown":[{"spell_level":5,"spell_slots":5,"spells":[{"spell":"flame strike"},{"spell":"mass inflict light wounds"},{"spell":"slay living"},{"spell":"spell resistance"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"fear"},{"spell":"freedom of movement"},{"spell":"inflict critical wounds"},{"spell":"order's wrath"},{"spell":"poison"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"animate dead"},{"spell":"blindness/deafness"},{"spell":"contagion"},{"spell":"deeper darkness"},{"spell":"dispel magic"},{"spell":"inflict serious wounds"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"bull's strength"},{"spell":"death knell"},{"spell":"false life"},{"spell":"hold person"},{"spell":"inflict moderate wounds"},{"spell":"silence"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cause fear"},{"spell":"command"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"inflict light wounds"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"stabilize"},{"spell":"virtue"}]}],"mystery":"bones","strength":19,"dexterity":18,"intelligence":6,"wisdom":16,"charisma":22,"baseatk":10,"cmb":19,"cmd":32,"feats":[{"feat":"Command Undead"},{"feat":"Extend Spell"},{"feat":"Improved Critical (longsword)"},{"feat":"Improved Initiative"},{"feat":"Martial Weapon Proficiency (longsword)"},{"feat":"Quicken Spell"},{"feat":"Weapon Focus (claw)"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Acrobatics","value":4,"special":"+12 to jump"},{"skill":"Linguistics","value":0},{"skill":"Perception","value":24},{"skill":"Perform (percussion instruments)","value":19},{"skill":"Sense Motive","value":8},{"skill":"Spellcraft","value":6},{"skill":"Survival","value":9}],"languages":["Common","Infernal","Necril"],"sq":["blessed life","divine swiftness","false humanity","oracle's curse (clouded vision)","revelations (armor of bones, bleeding wounds, death's touch, undead servitude)","sacred site"],"special_abilities":[{"type":"Missing Arm","kind":"Ex","details":"Asmoden is missing his left arm, and thus must drop or sheathe his longsword in order to make claw attacks. He can use Still Spell to cast spells while wielding his sword. During any round in which Asmoden's missing arm is visible to him, the huecuva must succeed at a DC 25 Will save to avoid being staggered. If a PC forcefully presents the arm to Asmoden (this is a move action), the huecuva takes a -5 penalty on this Will save that round. If Asmoden reclaims his arm, it reattaches instantly; he not only loses this special weakness, but also is healed of 4d6+20 points of damage and gains a second claw attack."}],"gear":"+2 Human-bane mithral longsword, 985 gp, crown of swords","before_combat":"Asmoden casts spell resistance, false life, desecrate (the possessed bells function as an altar for this spell's effects), bull's strength, and shield of faith before combat-most likely as soon as he sees the wall of force or hellfire column below deactivate because one or both infernal engines have shut down. He also activates his armor of bones ability before combat.","during_combat":"Asmoden casts quickened divine favor on the first round of combat (these effects are included in his statistics above). On following rounds, he uses Quicken Spell as needed to cast any other before-combat spells he hasn't yet cast. He prefers to hang back to cast spells at range, but if forced into melee, he uses Power Attack and focuses his wrath on Human foes if possible. He casts mass inflict light wounds whenever a herecite is brought below 30 hit points to heal his allies or harm intruders. If brought below 50 hit points, he casts sanctuary and uses inflict spells to heal himself before returning to combat.","morale":"Asmoden fights until destroyed, confident that the Devil's Bells will rejuvenate him.","source":"AP 100, Pathfinder RPG Bestiary 4 60, Pathfinder RPG Bestiary 3 150, Pathfinder RPG Advanced Player's Guide 42"},{"name":"Barzillai Thrune","cr":16,"xp":76800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"inquisitor of asmodeus","level":15}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"templates_applied":"advanced","init":10,"ac":30,"ac_touch":17,"ac_flat_footed":27,"ac_mods":"+11 armor, +4 deflection, +3 Dex, +2 natural","hp":206,"hd":"15d8+135","hd_value":15,"fort":20,"ref":12,"will":22,"defensive_abilities":["stalwart"],"resists":["fire 20"],"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+3 flaming impact heavy mace +20 (2d6+8/19-20 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"exploit weakness"},{"type":"greater bane","details":"15 rounds/day"},{"type":"judgment","details":"5/day, 2 simultaneous"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"},{"spell":"discern lies","details":"15 rounds/day"}]},{"frequency":"1/day","spells":[{"spell":"hold person","details":"DC 13; granted by the altar of Asmodeus in area E39"}]},{"frequency":"10/day","spells":[{"spell":"touch of fatigue"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":15,"spellsknown_concentration":22,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"flame strike"},{"spell":"greater command"},{"spell":"mark of justice"},{"spell":"spell resistance"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"detect scrying"},{"spell":"dismissal"},{"spell":"hold monster"},{"spell":"sending"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"nondetection"},{"spell":"searing light"},{"spell":"speak with dead"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"cure moderate wounds"},{"spell":"death knell"},{"spell":"invisibility"},{"spell":"lesser restoration"},{"spell":"spiritual weapon"},{"spell":"weapon of awe"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"burst bonds"},{"spell":"command"},{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"brand"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"light"},{"spell":"read magic"}]}],"spelldomains":"Torture inquisition","strength":20,"dexterity":16,"constitution":24,"intelligence":15,"wisdom":24,"charisma":18,"baseatk":11,"cmb":16,"cmb_special":"+19 bull rush","cmd":33,"feats":[{"feat":"Combat Casting"},{"feat":"Coordinated Defense"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Improved Critical (heavy mace)"},{"feat":"Iron Will"},{"feat":"Outflank"},{"feat":"Power Attack"},{"feat":"Precise Strike"},{"feat":"Shake It Off"},{"feat":"Shielded Caster"},{"feat":"Toughness"},{"feat":"Weapon Focus (heavy mace)"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Craft (torture device)","value":13},{"skill":"Intimidate","value":25},{"skill":"Knowledge (arcana, planes, religion)","value":20},{"skill":"Knowledge (local, nobility)","value":12},{"skill":"Linguistics","value":12},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":22},{"skill":"Spellcraft","value":20}],"languages":["Common","Aklo","Azlanti","Draconic","Dwarven","Elven","Giant","Gnome","Halfling","Infernal","Shadowtongue","Strix","Varisian"],"sq":["critical precision","monster lore +7","solo tactics","stern gaze +7","torturer's presence","track +7"],"special_abilities":[{"type":"Heartless","kind":"Su","details":"Barzillai's heart is ensconced deep under Kintargo in the soul anchor. In its place he has stashed a magical puzzle box known as a Chelish Crux. See Concluding the Adventure for more information on this puzzle box and its contents. Barzillai's heartless condition renders him immune to bleed damage and grants him a +4 bonus on all saving throws versus death effects. It also grants him the benefits of the advanced creature simple template. If reduced to negative hit points, Barzillai becomes staggered but doesn't fall unconscious. If his hit-point total drops to a negative amount of hit points that equals or exceeds his Constitution score (-24 hp at his current Constitution score), he doesn't die-he merely becomes stunned. This stunned condition can't be removed by any effect as long as he remains at -24 hp or fewer, but is removed immediately if he is healed above this total. A destruction or disintegrate spell (or another effect that completely destroys the body) or a death effect can kill him if the damage caused by the attack reduces him to -24 hp or fewer. Effects like flesh to stone, imprisonment, or trap the soul that normally bypass damage reduction instead invoke a clause in his with Mephistopheles-rather than suffering the normal effect from the spell or item, he is struck dead on the spot. (In the case of the talisman of pure good from area E31, a spike of iron impales Barzillai before retracting into the pit created while leaving his gear, and more importantly, his Chelish Crux, behind in a smoking heap-this foreshadows his torment in the infernal realm of Caina in the final adventure.) Finally, reducing him to -191 hp via any damage source results in the utter destruction of his body and kills him. If Barzillai has fast healing active as a result of his judgment of healing, the fast healing effect continues to heal damage until he is actually killed. This healing can potentially restore him to full mobility if it brings him above -24 hp. This ability, plus his PC-equivalent wealth, increases his CR by 2."}],"gear":"+5 improved fire resistance breastplate, +3 flaming impact heavy mace, belt of physical perfection +4, boots of speed, Chelish Crux, cloak of resistance +4, headband of inspired wisdom +4, ring of protection +4, adamantine and ruby holy symbol of Asmodeus worth 4,000 gp, gold ring with five rubies worth 2,500 gp, ring of spell storing, scroll of blade barrier, scroll of geas/quest, scrolls of stoneskin (2), wand of cure critical wounds (17 charges), wand of order's wrath (21 charges)","before_combat":"Barzillai casts detect scrying and nondetection every day, and spell resistance, stoneskin (from a scroll), and weapon of awe before combat begins.","during_combat":"On the first round of combat, Barzillai activates his boots of speed as a free action, pronounces judgments of healing and justice as a swift action, and casts divine favor as a standard action. Barzillai uses ranged spells, preferring flame strike, greater command (to order foes to fall prone), hold monster, searing light, and spiritual weapon. In melee, he takes a swift action at the start of a round to imbue his mace with the bane weapon special ability. At fewer than 75 hit points, he casts sanctuary to recover before returning to battle. Barzillai uses his teamwork feats when he's adjacent to or flanking with allies, as summarized below. Coordinated Defense: He gains a +2 bonus to his CMD. Outflank: His flanking bonus on attack rolls increases to +4. Precise Strike: He deals +1d6 points of precision damage when he damages a foe he flanks. Shake It Off: He gains a +1 bonus on saves per adjacent ally (maximum +4). Shielded Caster: Barzillai gains a +4 bonus on concentration checks.","morale":"If reduced to fewer than 50 hit points, Barzillai uses his ring of spell storing to teleport to an unoccupied family estate in Egorian, where he has stashed enough supplies to recover from his wounds. It takes him a few days to arrange for a second teleport spell to be placed in his ring, after which he returns to Kintargo with allies in disguise, hoping to get revenge on the PCs. See Concluding the Adventure on page 61 for more information. Barzillai is incredibly hard to kill, but if he's stunned as a result of hit point loss, his allies try to take his body away to safety until he can be restored.","source":"AP 100, Pathfinder RPG Bestiary 294, Pathfinder RPG Advanced Player's Guide 38"},{"name":"Shensen","cr":11,"xp":12800,"race":"Half-Elf","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":8,"archetype":"Dawnflower dervish"},{"class":"fighter","level":4}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["elf","human"],"init":6,"senses":["low-light vision"],"ac":27,"ac_touch":19,"ac_flat_footed":20,"ac_mods":"+6 armor, +2 deflection, +6 Dex, +1 dodge, +2 natural","hp":106,"hd":"8d8+4d10+44","hd_value":12,"fort":8,"ref":13,"will":8,"save_mods":"+2 vs. enchantments; +4 vs. bardic performance, language-dependent, and sonic+4 morale bonus vs. charm and fear effects, Will: +1 vs. fear","immunities":["sleep"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"+1 flaming burst mithral scimitar +22 (1d6+15/15-20 plus 1d6 fire) or mwk whip +15 (1d3+6 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 24 rounds/day","details":"move action; countersong, distraction, fascinate [DC 20], inspire competence +6, inspire courage +4, suggestion [DC 20]"}],"spellsknown_caster":"bard","spellsknown_caster_level":8,"spellsknown_concentration":14,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"confusion"},{"spell":"cure serious wounds"},{"spell":"glibness"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blindness/deafness"},{"spell":"detect thoughts"},{"spell":"invisibility"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"cure light wounds"},{"spell":"disguise self"},{"spell":"grease"},{"spell":"undetectable alignment"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":10,"dexterity":22,"constitution":14,"intelligence":14,"wisdom":9,"charisma":22,"baseatk":10,"cmb":14,"cmd":29,"feats":[{"feat":"Arcane Strike"},{"feat":"Dervish Dance"},{"feat":"Dodge"},{"feat":"Improved Critical (scimitar)"},{"feat":"Iron Will"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (scimitar)"},{"feat":"Weapon Specialization (scimitar)"},{"feat":"Wind Stance"}],"skills":[{"skill":"Diplomacy","value":21},{"skill":"Knowledge (local)","value":9},{"skill":"Knowledge (nobility)","value":9},{"skill":"Knowledge (religion)","value":11},{"skill":"Linguistics","value":7},{"skill":"Perception","value":12},{"skill":"Perform (dance)","value":21},{"skill":"Perform (sing)","value":21},{"skill":"Spellcraft","value":17},{"skill":"Swim","value":23}],"languages":["Common","Aquan","Elven","Infernal","Tengu"],"sq":["armor training 1","battle dance","elf blood","meditative whirl","poison use","reincarnated","spinning spellcaster","versatile performances (dance, sing)"],"special_abilities":[{"type":"Battle Dance","kind":"Ex","details":"When Shensen uses bardic performance to inspire courage or inspire greatness, the bonuses granted are doubled but apply only to her (these bonuses are already adjusted accordingly in her special attacks above). All other functions of bardic performance function normally."},{"type":"Meditative Whirl","kind":"Ex","details":"Once per day when using battle dance, Shensen can spend a move action to apply the Quicken Spell metamagic feat to any cure spell she is about to cast (effectively spending a move action and a swift action to cast the spell); this doesn't alter the spell's level. Reincarnated Shensen was born a drow noble but was reincarnated into an aquatic Half-Elf; she retains her +2 bonuses to Intelligence, Wisdom, and Charisma from her birth heritage, and a +2 bonus to Dexterity from her current incarnation. She also retains proficiency with the hand crossbow and poison use, but rarely uses such weapons or tactics. She's lost all other drow abilities as the result of the reincarnation."},{"type":"Spinning Spellcaster","kind":"Ex","details":"Shensen gains a +4 bonus on concentration checks to cast spells defensively."}],"gear":"+2 mithral chain shirt, +1 flaming burst mithral scimitar, mwk whip, amulet of natural armor +2, belt of incredible dexterity +4, headband of alluring charisma +4, pearl of the sirines, ring of feather falling, ring of protection +2, earrings, noble's clothes, 74 gp, potion of fly (2), rod of wonder, wand of haste (10 charges), wand of sound burst (14 charges)","before_combat":"Shensen casts undetectable alignment every day.","during_combat":"Shensen opens a fight by using her rod of wonder, always eager to see what fate has in store, then stows the rod before moving on to casting ranged spells or entering melee combat. She uses her wand of haste once it appears she has to engage in melee combat, then activates her battle dance and Arcane Strike abilities (her attacks above have been adjusted to account for these bonuses) and prefers to remain mobile in combat, making full attacks only if surrounded. She relies on her spells and her wand of sound burst for ranged combat. She occasionally brings her rod of wonder back into the fight, sometimes a bit too often, intrigued and delighted as she is by the rod's random effects. Her bardic performances don't bolster allies, and as such she generally takes on a more aggressive role in battle, rather than a support function.","morale":"Shensen fights to the death if allies are in danger, but otherwise flees combat if reduced to 25 hit points or fewer-with the exception of combats involving apes or gorilla-like foes, in which case she'll flee combat if reduced to 50 hit points or less. Because there's nothing more frightening than an angry gorilla.","source":"AP 100, Pathfinder Campaign Setting: Inner Sea Magic 34"},{"name":"The Terrible Tup","cr":3,"xp":800,"race":"Goblin","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":1},{"class":"sorcerer","level":3}],"alignment":"NE","size":"Small","type":"humanoid","sub_types":["goblinoid"],"init":3,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+3 Dex, +1 natural, +1 size","hp":28,"hd":"3d6+1d8+11","hd_value":4,"fort":3,"ref":6,"will":4,"save_mods":"+4 to avoid catching on fire or to put himself out when on fire","resists":["fire 5"],"speed":[{"type":"land","speed":30}],"melee":"torch +2 (1d2-1 plus 1d4 fire) Range alchemist's fire +4 (1d6 fire plus 1d4 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 6 rounds/day","details":"countersong, distraction, fascinate [DC 12], inspire courage +1"},{"type":"claws","details":"2, 1d3, 5 rounds/day"}],"spellsknown_caster":"bard","spellsknown_caster_level":1,"spellsknown_concentration":3,"spellsknown":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"beguiling gift"},{"spell":"hideous laughter"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"know direction"},{"spell":"prestidigitation"},{"spell":"resistance    Sorcerer Spells Known"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"burning hands"},{"spell":"endure elements"},{"spell":"mage armor"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"spark"}]}],"bloodline":"draconic","strength":8,"dexterity":17,"constitution":14,"intelligence":12,"wisdom":8,"charisma":14,"baseatk":1,"cmb":-1,"cmd":12,"feats":[{"feat":"Burn! Burn! Burn!"},{"feat":"Eschew Materials"},{"feat":"Fire Hand"}],"skills":[{"skill":"Acrobatics","value":0,"special":"-4 when jumping"},{"skill":"Bluff","value":6},{"skill":"Craft (alchemy)","value":6},{"skill":"Disable Device","value":1},{"skill":"Disguise","value":7},{"skill":"Intimidate","value":7},{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (local)","value":6},{"skill":"Perform (act)","value":6},{"skill":"Perform (comedy)","value":8},{"skill":"Ride","value":4},{"skill":"Spellcraft","value":5},{"skill":"Stealth","value":12}],"languages":["Common","Goblin"],"sq":["bardic knowledge +1","bloodline arcana (energy spells that match bloodline energy deal +1 point of damage per die)"],"gear":"bagpipes (broken), curved smoking pipe, hobnail boots, leather bag full of newts, Medium leather kilt, mummer's hat with a huge feather, paper candle firework, portable alchemist's lab, puppeteer's booth, rat-skin sporran filled with clover, tindertwigs (19), torches (4), woolen mittens, yellow marbles (6), sheep named Deliverance equipped with a riding saddle and saddlebags, selection of gaudily painted glove puppets worth 150 gp as a set (including a huge magistrate holding a meat cleaver and a string of fake sausages, his stick-thin wife, a trio of masked rats, a dire corby, and a hell hound), potions of hideous laughter (2), alchemist's fire (7), fuse grenades (2), oil (12)","before_combat":"Tup prefers avoiding fights, instead setting his fires and running to watch their beauty from a safe distance. If confronted, he tries to intimidate opponents into backing down first.","during_combat":"Tup loves to burn things, friends and foes alike. If feeling playful, he uses beguiling gift to offer a potion of hideous laughter or a lit fuse grenade, but more often he simply turns to his favorite spell: burning hands. When spells run out, he instead lobs alchemist's fire.","morale":"Despite his bluster, the Terrible Tup is an unmitigated coward and flees if no one seems impressed or awed by his pyrotechnics.","source":"AP 100, Pathfinder RPG Bestiary 156"},{"name":"Gatlynn Keidros","cr":4,"xp":1200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":4},{"class":"slayer","level":1}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":21,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+9 armor, +2 Dex","hp":48,"hd":"5d10+14","hd_value":5,"fort":8,"ref":7,"will":0,"save_mods":"Will: +1 vs. fear","speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"mwk longsword +7 (1d8+1/19-20)","ranged":"mwk heavy crossbow +11 (1d10+2/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"studied target +1","details":"1 target"}],"strength":13,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":8,"charisma":12,"baseatk":5,"cmb":6,"cmd":20,"feats":[{"feat":"Crossbow Mastery"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Reload"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (heavy crossbow)"},{"feat":"Weapon Specialization (heavy crossbow)"}],"skills":[{"skill":"Acrobatics","value":0,"special":"-4 when jumping"},{"skill":"Bluff","value":5},{"skill":"Climb","value":3},{"skill":"Diplomacy","value":2},{"skill":"Disguise","value":5},{"skill":"Intimidate","value":8},{"skill":"Knowledge (nobility)","value":3},{"skill":"Perception","value":3},{"skill":"Ride","value":5},{"skill":"Stealth","value":4},{"skill":"Survival","value":3},{"skill":"Swim","value":1}],"languages":["Common"],"sq":["armor training 1","track +1"],"gear":"mwk full plate, mwk heavy crossbow with 20 bolts and 10 blunted bolts, mwk longsword, 14 gp, +1 silver crossbow bolts (10), potion of cure light wounds (2), potion of vanish (2), tanglefoot  bag (3), thunderstone (3)","during_combat":"Gatlynn always fights from a superior position, forcing opponents to climb walls, cross chasms, or brave other hazards to reach her sniping positions. If she lacks a secure perch, she instead opens fire to draw enemies back into a waiting ambush, where her allies engage the foes in melee, allowing her to pick off targets one by one. She readily changes up her ammunition to adapt to threats, or to deal nonlethal damage against foes to whom she wishes to show mercy.","morale":"Gatlynn is a practical fanatic, reasoning that she is of little use to her queen if she's dead, even if that death is glorious. She falls back if clearly outmatched or reduced below 15 hit points.","source":"AP 100, Pathfinder RPG Advanced Class Guide 53"},{"name":"Chessadril Odranata","cr":10,"xp":6400,"race":"drow","gender":"Female","age_category":"Adult","classes":[{"class":"expert","level":3},{"class":"rogue","level":7}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["elf"],"init":1,"senses":["darkvision 120 ft."],"ac":17,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+5 armor, +1 deflection, +1 Dex","hp":48,"hd":"10d8+3","hd_value":10,"fort":5,"ref":9,"will":9,"save_mods":"+4 vs. web-related spells and effects, +2 vs. enchantments","defensive_abilities":["evasion","trap sense +2","uncanny dodge"],"immunities":["sleep"],"sr":16,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"mwk shortsword +9 (1d6-1/19-20)","ranged":"+1 shock light crossbow +9 (1d8+1/19-20 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+4d6"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dancing lights"},{"spell":"darkness"},{"spell":"faerie fire"},{"spell":"spider climb"}]}],"strength":8,"dexterity":12,"constitution":10,"intelligence":14,"wisdom":14,"charisma":18,"baseatk":7,"cmb":6,"cmd":18,"feats":[{"feat":"Combat Expertise"},{"feat":"Deceitful"},{"feat":"Improved Feint"},{"feat":"Persuasive"},{"feat":"Spider Step"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Appraise","value":13},{"skill":"Bluff","value":19},{"skill":"Climb","value":3},{"skill":"Diplomacy","value":17},{"skill":"Disguise","value":15},{"skill":"Escape Artist","value":5},{"skill":"Handle Animal","value":12},{"skill":"Intimidate","value":16},{"skill":"Knowledge (dungeoneering)","value":9},{"skill":"Knowledge (geography)","value":9},{"skill":"Knowledge (local)","value":11},{"skill":"Knowledge (nobility)","value":9},{"skill":"Perception","value":15,"special":"+4 to hear the details of a conversation or to find concealed or secret objects [including doors and traps]"},{"skill":"Profession (merchant)","value":15},{"skill":"Ride","value":7},{"skill":"Sense Motive","value":14},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":9},{"skill":"Use Magic Device","value":15}],"languages":["Aklo","Drow Sign","Elven","Undercommon"],"sq":["exceptional resources","poison use","rogue talents (canny observer, coax information, finesse rogue)","trapfinding +3"],"special_abilities":[{"type":"Exceptional Resources","kind":"Ex","details":"As a highly successful Darklands merchant, Chessadril has wealth equal to that of a PC of her level. This increases her CR by +1."}],"gear":"+1 mithral chain shirt, +1 shock light crossbow, mwk shortsword, circlet of persuasion, cloak of resistance +2, ring of protection +1, backpack, climbing kit, concealed money pouch (DC 20 Perception; holds 15 pp and 71 gp), disguise kit, gold earrings (7, 50 gp each), small gold cheek piercings (50 gp each), chrysoberyls (7, 100 gp each), large emeralds (2, 3,000 gp each), riding gecko, exotic riding saddle, saddle bags, oil of darkness (5), potion of cure moderate wounds (5), potion of darkvision (5), potion of invisibility (2), acid (5), alchemist's fire (5), antitoxin (5), drow poison (10), spider sac (5)","before_combat":"Chessadril hates a fight, especially a fair one, and prefers to use stealth, deception, threats, bribery, or magic to avoid them whenever possible.","during_combat":"If cornered into combat, Chessadril uses spider climb to clamber to the ceiling or any other difficult-to-reach perch and opens fire with her crossbow. She poisons her bolts as soon as possible.","morale":"Chessadril flees combat at the first opportunity.","source":"AP 100, Pathfinder RPG Bestiary 114"},{"name":"Garavel","cr":6,"xp":2400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":7}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+6 armor, +2 Dex, +1 dodge","hp":60,"hd":"7d10+14","hd_value":7,"fort":7,"ref":5,"will":4,"save_mods":"Will: +2 vs. fear, +4 vs. mind-affecting effects","speed":[{"type":"land","speed":30}],"melee":"+1 falchion +13 (2d4+8/18-20) or sap +10 (1d6+3 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"heavy blades +1"}],"strength":16,"dexterity":14,"constitution":12,"intelligence":10,"wisdom":13,"charisma":10,"baseatk":7,"cmb":10,"cmd":23,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dazzling Display"},{"feat":"Disruptive"},{"feat":"Dodge"},{"feat":"Intimidating Prowess"},{"feat":"Persuasive"},{"feat":"Power Attack"},{"feat":"Weapon Focus (falchion)"},{"feat":"Weapon Specialization (falchion)"}],"skills":[{"skill":"Climb","value":6},{"skill":"Diplomacy","value":8},{"skill":"Intimidate","value":15},{"skill":"Perception","value":5},{"skill":"Survival","value":6},{"skill":"Swim","value":6}],"languages":["Common","Kelish"],"sq":["armor training 2"],"special_abilities":[{"type":"Pactmaster's Favor","details":"Garavel has a magical bolt implanted in the left side of his head that allows the Pactmasters to exert control over him. This implant provides a +4 resistance bonus on saves against mind-affecting effects, but as a side effect, Garavel can never gain the benefits of a morale bonus of any sort."}],"gear":"+1 horn lamellar armor, +1 falchion, sap, boots of the cat, cloak of resistance +1, elixir of hiding, Pactmaster's favor, ledger, potion of bear's endurance, potion of cure moderate wounds","source":"AP 100"},{"name":"Amaya Kaijitsu","cr":5,"xp":1600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":6,"archetype":"detective"}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+5 armor, +2 Dex, +1 dodge","hp":36,"hd":"6d8+6","hd_value":6,"fort":5,"ref":8,"will":7,"save_mods":"+4 bonus vs. illusion and to see through disguises and protections against divination","speed":[{"type":"land","speed":30}],"melee":"mwk quarterstaff +4 (1d6-1)","ranged":"mwk light crossbow +5 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 17 rounds/day","details":"careful teamwork, countersong, distraction, fascinate [DC 16], inspire competence +2, suggestion [DC 16]"}],"spellsknown_caster":"bard","spellsknown_caster_level":6,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":4,"spells":[{"spell":"ghostbane dirge"},{"spell":"invisibility"},{"spell":"mirror image"},{"spell":"zone of truth"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"cure light wounds"},{"spell":"expeditious retreat"},{"spell":"remove fear"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":8,"dexterity":15,"constitution":10,"intelligence":14,"wisdom":12,"charisma":16,"baseatk":4,"cmb":3,"cmd":16,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Lingering Performance"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Bluff","value":8},{"skill":"Climb","value":2},{"skill":"Craft (glass)","value":13},{"skill":"Diplomacy","value":8,"special":"+3 to gather information"},{"skill":"Heal","value":4},{"skill":"Intimidate","value":11},{"skill":"Knowledge (arcana)","value":8},{"skill":"Knowledge (history)","value":8},{"skill":"Knowledge (local)","value":12},{"skill":"Knowledge (nobility)","value":8},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":4},{"skill":"Perform (wind instruments)","value":12},{"skill":"Sense Motive","value":9},{"skill":"Sleight of Hand","value":6},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":10}],"languages":["Common","Halfling","Tien"],"sq":["arcane insight","eye for detail","lore master 1/day"],"gear":"+1 chain shirt, mwk light crossbow with 20 bolts and 5 +1 bolts, mwk quarterstaff, cloak of resistance +1, masterwork artisan's tools, masterwork silver flute, sunrod (5), 35 gp, potion of cure moderate wounds, scroll of daylight, alchemist's fire (4), caltrops (5)","before_combat":"Amaya casts expeditious retreat or invisibility if she wishes to avoid confrontation, or mirror image if she intends to engage a foe.","during_combat":"Amaya prioritizes her allies' safety in any fight, and uses her caltrops and ranged attacks to distract or redirect opponents. She prefers to fight alongside allies, and supports them with her bardic performance.","morale":"Amaya intends to rescue people from shadow monsters, not die a hero. She stays with her allies but encourages a safe retreat. If saving a friend means leaving a stranger to die, that is a burden she will bear.","source":"AP 100, Pathfinder RPG Advanced Player's Guide 81"},{"name":"Trazel Rainwater","cr":9,"xp":6400,"race":"fossegrim","gender":"Male","age_category":"Adult","classes":[{"class":"skald","level":5}],"alignment":"NE","size":"Medium","type":"fey","sub_types":["aquatic"],"init":9,"senses":["low-light vision"],"ac":24,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+4 armor, +5 Dex, +1 dodge, +4 natural","hp":118,"hd":"9d6+5d8+61","hd_value":14,"fort":11,"ref":12,"will":13,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["uncanny dodge"],"dr":"5/cold iron","speed":[{"type":"land","speed":30},{"type":"swim","speed":40}],"melee":"2 slams +13 (2d6+2)","ranged":"mwk bolas +13 (1d4+2 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drowning touch","details":"DC 17"},{"type":"enchanting music","details":"DC 20"},{"type":"rage power","details":"no escape"},{"type":"raging song","details":"17 rounds/day; inspired rage, song of marching"},{"type":"spell kenning","details":"1/day"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"water walk"}]},{"frequency":"3/day","spells":[{"spell":"quickened hydraulic torrent"}]}],"spellsknown_caster":"skald","spellsknown_caster_level":5,"spellsknown_concentration":11,"spellsknown":[{"spell_level":2,"spell_slots":4,"spells":[{"spell":"anonymous interaction"},{"spell":"blindness/deafness"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"expeditious retreat"},{"spell":"undetectable alignment"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":14,"dexterity":21,"constitution":19,"intelligence":10,"wisdom":16,"charisma":22,"baseatk":7,"cmb":9,"cmd":25,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (bolas)"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell-Like Ability (hydraulic torrent)"},{"feat":"Scribe Scroll"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Disguise","value":24},{"skill":"Intimidate","value":17},{"skill":"Knowledge (geography)","value":6},{"skill":"Knowledge (local)","value":7},{"skill":"Knowledge (nature)","value":6},{"skill":"Linguistics","value":5},{"skill":"Perception","value":16},{"skill":"Perform (sing)","value":14},{"skill":"Perform (string instruments)","value":22},{"skill":"Sense Motive","value":14},{"skill":"Sleight of Hand","value":18},{"skill":"Stealth","value":16},{"skill":"Swim","value":22}],"languages":["Common","Elven","Sylvan"],"sq":["amphibious","bardic knowledge +2","rage powers","transparency","treasure form","versatile performance (string instruments)"],"gear":"+1 glamered studded leather, mwk bolas (3), straight razor, belt of giant strength +2, hat of disguise, potion of cure moderate wounds (2), scroll of eagle's splendor (2), scroll of invisibility (2)","before_combat":"Trazel prefers to kill with a kiss rather than a blade, and woos suitors (or groups of them) to fight on his behalf. He always opens combat somewhere near water- city docks, riversides, lake shores-to take advantage of his natural gifts and escape should things go badly. If caught on land, he relies on mirror image for protection.","during_combat":"Trazel stays in the water whenever possible, gaining cover and becoming invisible while he inspires allies into a raging fury with his music. He uses enchanting music and charm person to bring individual victims close while using his hydraulic torrent to keep other opponents at bay.","morale":"Trazel uses his transparency or expeditious retreat to flee if brought below 50 hit points.","source":"AP 100, Pathfinder RPG Bestiary 4 114, Pathfinder RPG Advanced Class Guide 49"},{"name":"Sheko-Maru","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"red mantis assassin","level":3},{"class":"slayer","level":6}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":8,"ac":20,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 deflection, +4 Dex, +1 shield","hp":75,"hd":"3d8+6d10+24","hd_value":9,"fort":9,"ref":12,"will":6,"save_mods":"+2 vs. detect thoughts, discern lies, and similar mind-reading magic","defensive_abilities":["red shroud"],"speed":[{"type":"land","speed":30}],"melee":"+1 sawtooth sabre +12 (1d8+5/19-20 plus poison) or +1 sawtooth sabre +10 (1d8+5/19-20 plus poison), +1 sawtooth sabre +10 (1d8+4/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"prayer attack","details":"DC 17"},{"type":"sneak attack","details":"+3d6"},{"type":"studied target +2","details":"2 targets"}],"spellsknown_caster":"red mantis assassin","spellsknown_caster_level":3,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"disguise self"},{"spell":"long arm"},{"spell":"monkey fish"},{"spell":"true strike"}]}],"strength":14,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":8,"charisma":12,"baseatk":8,"cmb":10,"cmd":25,"feats":[{"feat":"Alertness"},{"feat":"Exotic Weapon Proficiency (sawtooth sabre)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Two-Weapon Defense"},{"feat":"Two-weapon Fighting"},{"feat":"Weapon Focus (sawtooth sabre)"},{"feat":"Weapon Specialization (sawtooth sabre)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":7},{"skill":"Climb","value":10},{"skill":"Craft (alchemy)","value":4},{"skill":"Disguise","value":8},{"skill":"Escape Artist","value":9},{"skill":"Heal","value":4},{"skill":"Intimidate","value":9},{"skill":"Knowledge (geography)","value":6},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":13},{"skill":"Ride","value":8},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":15},{"skill":"Survival","value":9},{"skill":"Swim","value":6}],"languages":["Common"],"sq":["slayer talents (foil scrutiny, poison use, ranger combat style [two-weapon combat])","track +3"],"gear":"+1 studded leather, +1 sawtooth sabre (2), cloak of resistance +1, ring of protection +1, brass ring on a leather thong, mask of the mantis, belladonna (2 doses), id moss (2 doses), large scorpion venom (2 doses), thunderstone (2)","before_combat":"Sheko-Maru is patient and observant, and quietly waits for opportunities to present themselves before making any moves. He likes to sow tension within groups, stealing one member's belongings and hiding them in another target's pack, or stealing food in the night and leaving crumbs on a potential victim's bedroll, and turns to his poisons, magic, and violence only once a party's members grow more suspicious of one another than of any outside threat. He studies two targets carefully and poisons his blades before leaping into the fray.","during_combat":"Sheko-Maru attacks from under cover of his red shroud ability, and rarely attacks more than two enemies at once without backup. His combat style is straightforward, relying on his poisoned blades to fell enemies before he melts back into concealment.","morale":"If dropped to fewer than 15 hit points, Sheko-Maru reactivates his red shroud ability so enemies don't have access to his corpse, but otherwise fights to the death.","source":"AP 100, Pathfinder Campaign Setting Inner Sea World Guide 282, Pathfinder RPG Advanced Class Guide 53"},{"name":"Lessaj Gilvrand","cr":8,"xp":4800,"race":"changeling","gender":"Female","age_category":"Adult","classes":[{"class":"investigator","level":9}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["changeling"],"init":2,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+4 armor, +2 deflection, +2 Dex, +1 natural","hp":53,"hd":"9d8+9","hd_value":9,"fort":3,"ref":8,"will":10,"save_mods":"+6 bonus vs. poison","defensive_abilities":["trap sense +3"],"speed":[{"type":"land","speed":30}],"melee":"+1 short sword +7 (1d6+2/19-20), claw +6 (1d4+1) or 2 claws +6 (1d4+1)","ranged":"hand crossbow +8 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"studied combat","details":"+4, 3 rounds"},{"type":"studied strike","details":"+3d6"}],"extractsprepared_caster":"investigator","extractsprepared_caster_level":9,"extractsprepared":[{"spell_level":3,"spells":[{"spell":"fly"},{"spell":"gaseous form"},{"spell":"haste"},{"spell":"water breathing"}]},{"spell_level":2,"spells":[{"spell":"alter self"},{"spell":"blur"},{"spell":"bull's strength"},{"spell":"resist energy"},{"spell":"spider climb"}]},{"spell_level":1,"spells":[{"spell":"cure light wounds"},{"spell":"detect secret doors"},{"spell":"detect undead"},{"spell":"disguise self"},{"spell":"expeditious retreat"},{"spell":"jump"}]}],"strength":10,"dexterity":14,"constitution":10,"intelligence":17,"wisdom":15,"charisma":10,"baseatk":6,"cmb":6,"cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Extra Inspiration"},{"feat":"Extra Investigator Talent"},{"feat":"Iron Will"},{"feat":"Run"}],"skills":[{"skill":"Acrobatics","value":2,"special":"+4 when jumping with a running start"},{"skill":"Craft (alchemy)","value":15,"special":"+9 to create alchemical items"},{"skill":"Diplomacy","value":7},{"skill":"Disable Device","value":16},{"skill":"Intimidate","value":12},{"skill":"Knowledge (local)","value":15},{"skill":"Linguistics","value":7},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":14},{"skill":"Use Magic Device","value":12}],"languages":["Common","Elven","Halfling","Orc","Skald","Varisian"],"sq":["alchemy (alchemy crafting +9)","inspiration (10/day)","investigator talents (combat inspiration, expanded inspiration, inspired alertness, perceptive tracking, quick study)","keen recollection","poison lore","swift alchemy","trapfinding +4"],"gear":"+1 studded leather, +1 short sword, hand crossbow with 20 bolts, ring of protection +2, tindertwig (10), 27 gp, potion of cure serious wounds, alchemist's fire (4), holy water (2), thunderstone","before_combat":"Lessaj rarely compromises her social situation with overt violence, and detests work involving murder and assassination. If she must engage someone, she downs her alter self extract to hide her identity and bull's strength and haste extracts to gain an advantage.","during_combat":"If the terrain allows, Lessaj relies on haste and either a spider climb or fly extract to gain a height advantage, attacking before maneuvering beyond an enemy's reach.","morale":"Lessaj uses her gaseous form extract to flee if reduced to fewer than half her hit points.","source":"AP 100, Pathfinder RPG Advanced Race Guide 184, Pathfinder RPG Advanced Class Guide 30"},{"name":"Hirakonu","cr":11,"xp":12800,"race":"ogre mage","gender":"Male","age_category":"Adult","classes":[{"class":"magus","level":3}],"alignment":"LN","size":"Large","type":"outsider","sub_types":["native","oni","shapechanger"],"init":8,"senses":["darkvision 60 ft.","low-light vision"],"ac":26,"ac_touch":15,"ac_flat_footed":21,"ac_mods":"+6 armor, +1 deflection, +4 Dex, +1 dodge, +5 natural, -1 size","hp":148,"hd":"3d8+8d10+91","hd_value":11,"hp_mods":"regeneration 5 (fire or acid)","fort":17,"ref":9,"will":10,"sr":22,"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":40}],"melee":"+1 nine-ring broadsword +19 (2d6+10/x3)","ranged":"mwk composite longbow +14 (2d6+9/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"arcane pool","details":"+1, 5 points"},{"type":"magus arcana","details":"pool strike"},{"type":"spell combat"},{"type":"spellstrike"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"}]},{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"invisibility"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"cone of cold"},{"spell":"deep slumber"},{"spell":"gaseous form"}]}],"spellsprepared_caster":"magus","spellsprepared_caster_level":3,"spellsprepared_concentration":7,"spellsprepared":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"chill touch"},{"spell":"shield"},{"spell":"shocking grasp"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"read magic"}]}],"strength":28,"dexterity":19,"constitution":27,"intelligence":18,"wisdom":12,"charisma":17,"baseatk":10,"cmb":20,"cmd":36,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+4 when jumping"},{"skill":"Bluff","value":16},{"skill":"Disguise","value":16},{"skill":"Fly","value":9},{"skill":"Intimidate","value":16},{"skill":"Knowledge (arcana)","value":15},{"skill":"Knowledge (geography)","value":8},{"skill":"Knowledge (history)","value":8},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (nature)","value":5},{"skill":"Knowledge (nobility)","value":8},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":12},{"skill":"Survival","value":7}],"languages":["Common","Draconic","Giant","Tengu","Tien"],"sq":["change shape (Small, Medium, or Large humanoid; alter self or giant form I)","spirit boon"],"special_abilities":[{"type":"Spirit Boon","kind":"Su","details":"Hirakonu is possessed by the spirit Tobun Rei, and while the spirit cannot control the oni's actions, it has spent a century whispering in his ear and slowly influencing his personality. While possessed by this spirit, Hirakonu can spend 5 minutes listening to the grief-stricken father's whispers to gain a +2 insight bonus on Perception and Sense Motive checks regarding children for 24 hours."}],"gear":"+2 chain shirt, +1 nine-ring broadsword, mwk composite longbow (+9 Str), belt of mighty constitution +2, 270 gp, pearl of power (1st level), potion of cure moderate wounds (2), potion of heroism, vambraces of defense","before_combat":"Hirakonu prefers to learn about potential enemies before fighting them, either changing shape to converse with them as a fellow traveler or becoming invisible to study them from afar.","during_combat":"Hirakonu relies heavily on his flight and increased mobility in combat. He casts shield before battle, and uses invisibility or darkness to disorient foes. While his hands tremble should he threaten innocents, he has no qualms about killing in combat.","morale":"A fugitive and survivor, Hirakonu flees when a battle turns against him, using gaseous form or invisibility to escape and wait for his regeneration to close his wounds.","source":"AP 100, Pathfinder RPG Bestiary 221, Pathfinder RPG Ultimate Magic 9"}];
